 }
 }
}
EOF

cat > providers.tf <<'EOF'
provider "aws" {
 region = var.aws_region

 default_tags {
 tags = local.common_tags
 }
}
EOF

cat > variables.tf <<'EOF'
variable "application_name" {
 description = "Name of the application for resource naming and tagging"
 type = string
}

variable "aws_region" {
 description = "AWS region where resources will be created"
 type = string
 default = "us-west-2"
}

variable "environment" {
 description = "Target deployment environment"
 type = string

 validation {
 condition = contains(["dev", "staging", "prod"], var.environment)
 error_message = "Environment must be dev, staging, or prod."
 }
}

variable "force_destroy" {
 description = "Whether to allow the bucket to be destroyed even if it contains objects"
 type = bool
 default = false
}
EOF

cat > locals.tf <<'EOF'
locals {
 bucket_name = lower("${var.application_name}-${var.environment}-site")

 common_tags = {
 Environment = var.environment
 ManagedBy = "Terraform"
 Project = var.application_name
 }
}
EOF

cat > main.tf <<'EOF'
resource "aws_s3_bucket" "main" {
 bucket = local.bucket_name
 force_destroy = var.force_destroy

 tags = merge(local.common_tags, {
 Name = local.bucket_name
 })
}

resource "aws_s3_bucket_public_access_block" "main" {
 bucket = aws_s3_bucket.main.id

 block_public_acls = false
 block_public_policy = false
 ignore_public_acls = false
 restrict_public_buckets = false
}

resource "aws_s3_bucket_website_configuration" "main" {
 bucket = aws_s3_bucket.main.id

 index_document {
 suffix = "index.html"
 }

 error_document {
 key = "error.html"
 }
}

resource "aws_s3_bucket_policy" "main" {
 bucket = aws_s3_bucket.main.id

 depends_on = [aws_s3_bucket_public_access_block.main]

 policy = jsonencode({
 Version = "2012-10-17"
 Statement = [
 {
 Sid = "PublicReadGetObject"
 Effect = "Allow"
 Principal = "*"
 Action = "s3:GetObject"
 Resource = "${aws_s3_bucket.main.arn}/*"
 }
 ]
 })
}
EOF

cat > outputs.tf <<'EOF'
output "bucket_name" {
 description = "Name of the S3 bucket hosting the static website"
 value = aws_s3_bucket.main.bucket
}

output "website_endpoint" {
 description = "Regional website endpoint for the S3 static website"
 value = aws_s3_bucket_website_configuration.main.website_endpoint
}
EOF

cat > README.md <<'EOF'
